export function used(input) {
  const base = typeof input === 'number' ? input : 0;
  const doubled = base * 2;
  const label = `used:${doubled}`;
  return { label, value: doubled };
}

export function alsoUsed(items) {
  const list = Array.isArray(items) ? items : [];
  let total = 0;
  for (const item of list) {
    if (typeof item === 'number' && Number.isFinite(item)) {
      total += item;
    }
  }
  return { count: list.length, total };
}

export function unusedBig(config) {
  // A deliberately large, never-imported export. If the linker is working,
  // this whole body is replaced with a ReducerReachabilityViolation stub.
  const settings = Object.assign(
    {
      retries: 3,
      backoffMs: 250,
      maxBackoffMs: 8000,
      jitter: true,
      timeoutMs: 30000,
      verbose: false,
    },
    config || {},
  );
  const schedule = [];
  let delay = settings.backoffMs;
  for (let attempt = 0; attempt < settings.retries; attempt += 1) {
    const jittered = settings.jitter ? delay + Math.floor(Math.random() * 100) : delay;
    schedule.push({
      attempt,
      delayMs: Math.min(jittered, settings.maxBackoffMs),
      deadline: Date.now() + settings.timeoutMs,
    });
    delay = Math.min(delay * 2, settings.maxBackoffMs);
  }
  const summary = schedule
    .map((s) => `attempt ${s.attempt} after ${s.delayMs}ms (deadline ${s.deadline})`)
    .join('; ');
  if (settings.verbose) {
    console.log(`unusedBig schedule: ${summary}`);
  }
  return { settings, schedule, summary };
}
